    <?php if ($q['status'] === 'sent'): ?><form method="post" action="/devis/<?= e($q['ref']) ?>/reponse<?= $tq ?>" style="display:inline"><?= csrf_field() ?><input type="hidden" name="t" value="<?= e($q['access_token']) ?>"><button class="btn btn-a" name="action" value="accept">✓ Accepter le devis</button> <button class="btn btn-g" name="action" value="decline">Refuser</button></form><?php endif; ?></div>
  <?php else: ?><div class="panel"><h2>Demande en cours de traitement</h2><p>Un conseiller prépare votre devis chiffré en FCFA. Vous serez prévenu(e) par e-mail et WhatsApp dès qu'il est prêt.</p></div><?php endif; ?>
  <div class="panel"><h2>Votre demande</h2><?php foreach ($items as $it): ?><p><b><?= e($it['name']) ?></b> × <?= (int) $it['qty'] ?><br><small class="muted"><?= e(implode(' · ', array_map(fn($x) => $x[0] . ' : ' . $x[1], jd($it['summary'])))) ?></small></p><?php endforeach; ?><?php if ($q['message']): ?><p><?= nl2br(e($q['message'])) ?></p><?php endif; ?></div>
